-- Phase 3 remediation (F-04) — document storage contract.
-- Forward-only. Migration 020 is not edited.
--
-- 020 let the client choose storage_key and only rejected URL-shaped values. A client could
-- therefore register a guessable key, a key under another tenant's prefix, or a key that points
-- at another subject's object. This migration moves key ownership to the database:
--
--   * storage_key is generated by the database on INSERT (a client value is ignored and
--     overwritten). It is 256 bits of randomness under a tenant prefix:
--       obj/<tenant uuid>/<64 hex>
--     It contains no subject id, no file name, no extension and no filesystem path.
--   * the key's tenant segment must equal tenant_id (CHECK), and the key is globally unique.
--   * the subject (learner / guardian / staff) must exist in the SAME tenant (trigger; RLS also
--     applies because the trigger runs as the invoker).
--   * identity columns are immutable; the only permitted change is archiving (one way).
--   * storage_status is 'metadata_only'. No object exists for any row. A later migration that
--     introduces object storage must widen this CHECK deliberately.
--
-- No SECURITY DEFINER function is added; both trigger functions run as the invoker.

ALTER TABLE directory_documents
  ADD COLUMN storage_status text NOT NULL DEFAULT 'metadata_only'
    CONSTRAINT directory_documents_storage_status_chk CHECK (storage_status IN ('metadata_only'));

-- Rows written under 020 carry client-chosen keys. No object was ever stored for them, so they are
-- replaced by server-generated keys before the stricter constraints are added.
UPDATE directory_documents
   SET storage_key = 'obj/' || tenant_id::text || '/'
                     || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');

ALTER TABLE directory_documents
  DROP CONSTRAINT directory_documents_storage_key_shape;

ALTER TABLE directory_documents
  ADD CONSTRAINT directory_documents_storage_key_shape CHECK (
    storage_key ~ '^obj/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{64}$'
    AND split_part(storage_key, '/', 2) = tenant_id::text
  );

ALTER TABLE directory_documents
  ADD CONSTRAINT directory_documents_storage_key_uniq UNIQUE (storage_key);

-- File names are display metadata, but they will end up in Content-Disposition headers.
-- NOT VALID: enforced for every new or updated row without scanning rows written before this contract.
ALTER TABLE directory_documents
  ADD CONSTRAINT directory_documents_file_name_safe CHECK (
    file_name !~ '[\\/[:cntrl:]]' AND trim(file_name) NOT IN ('.', '..')
  ) NOT VALID;

-- ---------------------------------------------------------------- insert guard
CREATE FUNCTION public.directory_documents_before_insert() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  v_found boolean;
BEGIN
  IF NEW.subject_type = 'learner' THEN
    SELECT true INTO v_found FROM public.learners l
     WHERE l.id = NEW.subject_id AND l.tenant_id = NEW.tenant_id;
  ELSIF NEW.subject_type = 'guardian' THEN
    SELECT true INTO v_found FROM public.guardians g
     WHERE g.id = NEW.subject_id AND g.tenant_id = NEW.tenant_id;
  ELSE
    SELECT true INTO v_found FROM public.staff_members s
     WHERE s.id = NEW.subject_id AND s.tenant_id = NEW.tenant_id;
  END IF;
  IF v_found IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'document subject does not exist in this tenant' USING ERRCODE = '23503';
  END IF;

  -- Any client-supplied key is discarded. The database is the only source of keys.
  NEW.storage_key := 'obj/' || NEW.tenant_id::text || '/'
                     || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  NEW.storage_status := 'metadata_only';
  RETURN NEW;
END;
$$;

CREATE TRIGGER directory_documents_before_insert
  BEFORE INSERT ON directory_documents
  FOR EACH ROW EXECUTE FUNCTION public.directory_documents_before_insert();

-- ---------------------------------------------------------------- update guard
CREATE FUNCTION public.directory_documents_before_update() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
     OR NEW.subject_type IS DISTINCT FROM OLD.subject_type
     OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
     OR NEW.doc_type IS DISTINCT FROM OLD.doc_type
     OR NEW.file_name IS DISTINCT FROM OLD.file_name
     OR NEW.content_type IS DISTINCT FROM OLD.content_type
     OR NEW.byte_size IS DISTINCT FROM OLD.byte_size
     OR NEW.storage_key IS DISTINCT FROM OLD.storage_key
     OR NEW.storage_status IS DISTINCT FROM OLD.storage_status
     OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'directory document identity and storage fields are immutable'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.archived_at IS NOT NULL AND NEW.archived_at IS DISTINCT FROM OLD.archived_at THEN
    RAISE EXCEPTION 'an archived directory document cannot be changed' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER directory_documents_before_update
  BEFORE UPDATE ON directory_documents
  FOR EACH ROW EXECUTE FUNCTION public.directory_documents_before_update();

REVOKE ALL ON FUNCTION public.directory_documents_before_insert() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.directory_documents_before_update() FROM PUBLIC;
